\label{lem:g-consequence}
The polynomial $g$ belongs to $\langle q\rangle^T$. Consequently, modulo $I+\mathcal M_{n,0}^{(4)}$, we have
\begin{equation} 
\label{equacaoj1maior}
X[x_a,x_b]x_c[x_d,x_e]
\equiv
X[x_c,x_b]x_a[x_d,x_e] -X[x_c,x_a]x_b[x_d,x_e],
\end{equation}
for every nonempty monomial $X$.

\label{lem:first-index-larger-middle}
The space $\mathcal M_{n,s}^{(4)}$, $1\leq s\leq n-5$,
is generated, modulo
$I+\sum_{k=0}^{s-1}\mathcal M_{n,k}^{(4)}$, by the polynomials
\[
x_{l_1}\cdots x_{l_r}
[x_{j_1},x_{i_1}]
x_{t_1}\cdots x_{t_s}
[x_{j_2},x_{i_2}]
\in\mathcal M_{n,s}^{(4)}
\]
under the condition $j_1>t_s$.

\label{lem:st3-consequence}
We have
$x_6[x_5,x_1]\operatorname{St}_3(x_4,x_3,x_2)
\in\langle p\rangle^T$. More precisely,
\begin{align*}
x_6[x_5,x_1]\operatorname{St}_3(x_4,x_3,x_2)
={}&x_6[x_5,x_1][x_3,x_2]x_4
-x_6[x_5,x_1][x_4,x_2]x_3+x_6[x_5,x_1][x_4,x_3]x_2.
\end{align*}

\label{lem:st3-middle-word}

Let $X$ be a nonempty monomial and let
$u=x_{t_1}\cdots x_{t_m}$, where $m\geq0$.
Set $n=\deg X+m+5$.
Then, modulo $I+\sum_{r=0}^{m}\mathcal M_{n,r}^{(4)}$, we have
\begin{equation}\label{equacaoj2maior}
X[x_a,x_b]ux_c[x_d,x_e]
\equiv X[x_a,x_b]ux_d[x_c,x_e]
-X[x_a,x_b]ux_e[x_c,x_d].
\end{equation}

\label{lem:linear-independence-B4}
The polynomials in $\mathcal B_n^{(4)}$ are linearly independent
modulo $P_n\cap\operatorname{Id}^{z}(D_0)$.

\label{idempotents}
Every $G$-grading $\Gamma$ on $D_0$ is isomorphic to a grading
$\Gamma'$ in which $e_{22}$ and $e_{33}$ are homogeneous of degree $1_G$.

\label{elementoshomogeneos}
A $G$-grading $\Gamma$ on $D_0$ is elementary if and only if
$e_{22},e_{33},e_{12},e_{23},e_{34}$ are homogeneous.

\label{e22e33}
A $G$-grading $\Gamma$ on $D_0$ is elementary if and only if
$e_{22},e_{33}\in(D_0)_{1_G}$.

For the algebra $\mathcal{A}_1$ we have:
    \begin{enumerate}
        \item[(1)] $\textnormal{Id}^{\mathbb{Z}_2}(\mathcal{A}_1)= \langle y_1[y_2,y_3][y_4,y_5]y_6, z_1 \rangle_{T_{\mathbb{Z}_2}}$.
        \item[(2)] $c_n^{\mathbb{Z}_2}(\mathcal{A}_1)=2^{n-3}n(n-1)(n-4)+2n(n-1)$, for $n\geq 7$. 
    \end{enumerate}

\label{sec6:prop-a2-oneodd}
For every $n\geq3$, the polynomials in \eqref{sec6:a2-oneodd}
are linearly independent modulo
$\textnormal{Id}^{\mathbb Z_2}(\mathcal A_2)$. Moreover, $c_{n-1,1}(\mathcal A_2)=n(n-1)c_{n-2}(UT_2)$, for all $n\geq3.$

\label{sec7:prop-a3-even}
For every $n\geq3$, the monomials in \eqref{sec7:a3-even} are linearly independent modulo
$\textnormal{Id}^{\mathbb Z_2}(\mathcal A_3)$. Moreover, $c_{n,0}(\mathcal A_3)=2n-1,$ for all $n\geq3.$

\label{sec7:prop-a3-oneodd}
For every $n\geq3$, the monomials in \eqref{eq:A3-one-odd-normal}
are linearly independent modulo
$\operatorname{Id}^{\mathbb Z_2}(\mathcal A_3)$. Moreover,
$c_{n-1,1}(\mathcal A_3)
=2n(n-1)+n(n-1)(n-2)2^{n-3}$, for all $n\geq3.$

\label{sec8:prop-a4-even}
For every $n\geq 4$, the monomials in \eqref{sec8:a4-even} are linearly
independent modulo $\textnormal{Id}^{\mathbb Z_2}(\mathcal A_4)$. Moreover, $c_{n,0}(\mathcal A_4)=n(n-1),$ for all $n\geq 4$.

\label{sec8:prop-a4-oneodd}
For every $n\geq3$, the monomials in \eqref{sec8:a4-oneodd}
are linearly independent modulo
$\textnormal{Id}^{\mathbb Z_2}(\mathcal A_4)$.
Moreover, $c_{n-1,1}(\mathcal A_4)=n+n(n-1)2^{n-2}$, for all $n\geq3$.

\label{sec8:thm-a7}
For the superalgebra $\mathcal A_7$, the following statements hold.
\begin{enumerate}
    \item
    The polynomials $y_1[y_2,y_3]y_4,$ $ z_1z_2z_3,$ $[y_1,y_2]z_3,$ $y_1z_2z_3$ and $ z_1[y_2,y_3]y_4$ generate $\textnormal{Id}^{\mathbb Z_2}(\mathcal A_7)$ as a $T_{\mathbb Z_2}$-ideal.

    \item $c_n^{\mathbb Z_2}(\mathcal A_7)=c_n^{\mathbb Z_2}(\mathcal A_4)
    =n\bigl(2n+n(n-1)2^{n-3}-1\bigr)$, for all  $n\geq3$.
\end{enumerate}

\label{sec9:prop-a6-even}
For every $n\geq 3$, the polynomials in \eqref{sec9:a6-even}
are linearly independent modulo
$\textnormal{Id}^{\mathbb Z_2}(\mathcal A_6)$. Moreover, $c_{n,0}(\mathcal A_6)
=c_n(UT_2)=2^{n-1}(n-2)+2$ for all {$n\geq3.$}

\label{sec9:prop-a6-oneodd}
For every $n\geq 3$, the polynomials in \eqref{sec9:a6-oneodd}
are linearly independent modulo
$\textnormal{Id}^{\mathbb Z_2}(\mathcal A_6)$. Moreover, $c_{n-1,1}(\mathcal A_6)
=2n\,c_{n-1}(UT_2)
=2n\bigl(2^{n-2}(n-3)+2\bigr)$, for all $n\geq3.$

\label{sec9:prop-a6-twoodd}
For every $n\geq3$, the polynomials in \eqref{sec9:a6-twoodd}
are linearly independent modulo
$\textnormal{Id}^{\mathbb Z_2}(\mathcal A_6)$. Moreover, $c_{n-2,2}(\mathcal A_6)
=n(n-1)c_{n-2}(UT_2)
=n(n-1)\bigl(2^{n-3}(n-4)+2\bigr),$ for all $n\geq3.$

\label{sec10:prop-a8-twoodd}
For every $n\geq4$, the monomials in \eqref{sec10:a8-twoodd}
are linearly independent modulo
$\textnormal{Id}^{\mathbb Z_2}(\mathcal A_8)$. Moreover, $c_{n-2,2}(\mathcal A_8)
=n(n-1)(2^{n-1}-1),$ for all $n\geq4.$
